class Solution {
public:
    vector<int> addToArrayForm(vector<int>& num, int k) {
        vector<int> res;
        int i = (int)num.size() - 1;
        while (i >= 0 || k > 0) {
            if (i >= 0) k += num[i--];
            res.push_back(k % 10);
            k /= 10;
        }
        reverse(res.begin(), res.end());
        return res;
    }
};

class Solution {
    public List<Integer> addToArrayForm(int[] num, int k) {
        List<Integer> res = new ArrayList<>();
        int i = num.length - 1;
        while (i >= 0 || k > 0) {
            if (i >= 0) k += num[i--];
            res.add(k % 10);
            k /= 10;
        }
        Collections.reverse(res);
        return res;
    }
}

var addToArrayForm = function(num, k) {
    const res = [];
    let i = num.length - 1;
    while (i >= 0 || k > 0) {
        if (i >= 0) {
            k += num[i--];
        }
        res.push(k % 10);
        k = Math.floor(k / 10);
    }
    return res.reverse();
};
